const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
fetch('experiment.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{
 document.getElementById('run-state').textContent='Selected result · 66.7%';
 document.getElementById('run-detail').textContent='GPT-5.6 Luna (max) · Phase 1, Round 4 · 4 of 6 trials passed. All six passed the model and effort audit.';
 document.getElementById('score-chart').innerHTML='<div class="bar-row"><span>Round 4</span><div class="bar-track" role="img" aria-label="4 of 6 trials passed, 66.7 percent"><div class="bar-fill" style="width:66.6667%"></div></div><span class="bar-value">66.7%</span></div>';
 document.getElementById('scores').innerHTML='<tr><td>Round 4</td><td>2 / 3</td><td>2 / 3</td><td>4 / 6</td><td><span class="tag kept">Selected</span></td></tr>';
 document.getElementById('round-content').innerHTML=`<h3>A practical experiment guide</h3><p>The retained extension is <code>instructions.md</code>. It guides the agent to track accepted measurements, keep training and prediction features consistent, balance discovery with ranking, validate against the task metric, and check the exported predictor.</p><p>These are instructions the agent follows while writing and running its own task code. This selected bundle has no additional executable tools or standalone skills. The animation above illustrates the broader search space; illustrative components are not included in this version.</p><p>This was the best retained result during search. Six trials do not establish a stable improvement over native Codex or performance on unseen tasks.</p><a class="data-link" href="selected-instructions.md" download>Download the selected instructions</a><details><summary>Read the actual instruction file</summary><pre>${esc(d.instructions)}</pre></details><details><summary>Inspect the six scored trials</summary><ul class="trial-list">${d.trials.map(t=>`<li>${esc(t.task)} · ${esc(t.trial)}: ${t.reward===1?'Pass':'Fail'}</li>`).join('')}</ul></details><details><summary>Source fingerprint</summary><pre>${esc(d.sha256)}</pre></details>`;
 document.getElementById('updated').textContent='Snapshot: '+new Date(d.updated_at).toLocaleString('en-US',{timeZone:'UTC'})+' UTC';
}).catch(()=>{document.getElementById('run-state').textContent='Results unavailable';document.getElementById('run-detail').textContent='Reload to retrieve the published snapshot.';});
